import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Kh, int Kw,
    int stride, int padding,
    int Hout, int Wout)
{
  constexpr int Threads    = 256;
  constexpr int PVec       = 4;
  constexpr int CoPerBlock = 16;

  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);

  const int tid      = threadIdx.x;
  const int n        = blockIdx.z;
  const int co_tile  = blockIdx.y;
  const int co_base  = co_tile * CoPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sYn = (int64_t)Cout * Hout * Wout;

  // Global tensors using CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride((int64_t)H * Win, (int64_t)Win, (int64_t)1)
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1)
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, Cin, Kh, Kw),
      make_stride((int64_t)Cin * Kh * Kw, (int64_t)Kh * Kw, (int64_t)Kw, (int64_t)1)
  );

  // Shared memory tensor for weight tile (CoPerBlock output channels, full Cin*Kh*Kw)
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(CoPerBlock, Cin, Kh, Kw),
      make_stride(Cin * Kh * Kw, Kh * Kw, Kw, 1)
  );

  // Cooperatively load the weight tile into shared memory
  const int wtile_elems = CoPerBlock * Cin * Kh * Kw;
  for (int idx = tid; idx < wtile_elems; idx += Threads) {
    int rem   = idx;
    int kw_   = rem % Kw;   rem /= Kw;
    int kh_   = rem % Kh;   rem /= Kh;
    int cin_  = rem % Cin;  rem /= Cin;
    int cc    = rem;

    int co = co_base + cc;
    T wval = T(0);
    if (co < Cout) {
      wval = mW(co, cin_, kh_, kw_);
    }
    sW(cc, cin_, kh_, kw_) = wval;
  }
  __syncthreads();

  // Precompute the output pixel coordinates handled by this thread
  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  // Accumulators, seeded with bias
  float acc[CoPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    float bval = 0.0f;
    if (B != nullptr && co < Cout) {
      bval = (float)B[co];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  for (int cin = 0; cin < Cin; ++cin) {
    for (int kh = 0; kh < Kh; ++kh) {
      for (int kw = 0; kw < Kw; ++kw) {
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          int p = p_idx[i];
          if (p >= P_total) continue;

          int ih = oh_arr[i] * stride - padding + kh;
          int iw = ow_arr[i] * stride - padding + kw;

          float xval = 0.0f;
          if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
            xval = (float)mX(cin, ih, iw);
          }

          #pragma unroll
          for (int cc = 0; cc < CoPerBlock; ++cc) {
            float wval = (float)sW(cc, cin, kh, kw);
            acc[cc][i] += xval * wval;
          }
        }
      }
    }
  }

  // Epilogue: write results
  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    if (co >= Cout) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(co, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  int N   = (int)x_c.size(0);
  int Cin = (int)x_c.size(1);
  int H   = (int)x_c.size(2);
  int Win = (int)x_c.size(3);

  int Cout = (int)w_c.size(0);
  TORCH_CHECK((int)w_c.size(1) == Cin, "in_channels mismatch between x and w");
  int Kh = (int)w_c.size(2);
  int Kw = (int)w_c.size(3);

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int Hout = (H + 2 * padding - Kh) / stride + 1;
  int Wout = (Win + 2 * padding - Kw) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && (int)b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads    = 256;
  constexpr int PVec       = 4;
  constexpr int CoPerBlock = 16;

  int P_total = Hout * Wout;
  int PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + CoPerBlock - 1) / CoPerBlock),
      (unsigned)N
  );

  size_t shmem_bytes = (size_t)CoPerBlock * Cin * Kh * Kw * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_kernel<float><<<grid, block, shmem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      N, Cin, H, Win,
      Cout, Kh, Kw,
      stride, padding,
      Hout, Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(torch.empty(self.out_channels, self.in_channels,
                                                 self.kernel_size, self.kernel_size))
        self.bias = nn.Parameter(torch.empty(self.out_channels))

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            int(self.stride),
            int(self.padding),
        )

