    if (p < P_total) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  // Accumulators, seeded with bias
  float acc[CoPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    float bval = 0.0f;
    if (B != nullptr && co < Cout) {
      bval = (float)B[co];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  for (int cin = 0; cin < Cin; ++cin) {
    for (int kh = 0; kh < Kh; ++kh) {
      for (int kw = 0; kw < Kw; ++kw) {
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          int p = p_idx[i];
          if (p >= P_total) continue;

          int ih = oh_arr[i] * stride - padding + kh;
          int iw = ow_arr[i] * stride - padding + kw;

          float xval = 0.0f;
          if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
            xval = (float)mX(cin, ih, iw);
          }

          #pragma unroll
          for (int cc = 0; cc < CoPerBlock; ++cc) {
            float wval = (float)sW(cc, cin, kh, kw);
            acc[cc][i] += xval * wval;
          }
        }
      }
    }
  }

  // Epilogue: write results
  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    if (co >= Cout) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(co, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  int N   = (int)x_c.size(0);
  int Cin = (int)x_c.size(1);
  int H   = (int)x_c.size(2);
  int Win = (int)x_c.size(3);

  int Cout = (int)w_c.size(0);
  TORCH_CHECK((int)w_c.size(1) == Cin, "in_channels mismatch between x and w");
  int Kh = (int)w_c.size(2);
  int Kw = (int)w_c.size(3);

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int Hout = (H + 2 * padding - Kh) / stride + 1;
  int Wout = (Win + 2 * padding - Kw) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && (int)b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads    = 256;
  constexpr int PVec       = 4;
  constexpr int CoPerBlock = 16;

  int P_total = Hout * Wout;
  int PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + CoPerBlock - 1) / CoPerBlock),
      (unsigned)N
  );

  size_t shmem_bytes = (size_t)CoPerBlock * Cin * Kh * Kw * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_kernel<float><<<grid, block, shmem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      N, Cin, H, Win,
      Cout, Kh, Kw,
      stride, padding,
      Hout, Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
